/**
 * Opt-in check of live transcription against the real Gemini Live API
 * (AIC_LIVE_TESTS=1, key from .env.local). Plays the Phase 0 speech clips
 * (spikes/fixtures/audio, generated by `npm run gen-audio` in spikes/) through
 * the whole engine pipeline in real time and checks the saved transcript.
 * About a minute; costs well under a cent.
 */
import { randomBytes } from 'node:crypto';
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { encodeWav, readWav, transcriptSimilarity } from '@aic/core';
import type { EngineEvents, LiveTranscriptUpdate } from '@aic/ipc';
import { afterAll, describe, expect, it } from 'vitest';
import { createEngine } from './engine';

const root = join(__dirname, '../../../..');
const AUDIO = join(root, 'spikes/fixtures/audio');

function devKey(): string | undefined {
  try {
    const text = readFileSync(join(root, '.env.local'), 'utf8');
    return /^\s*(?:export\s+)?(?:GEMINI_API_KEY|GOOGLE_API_KEY|API_KEY)\s*[=:]\s*"?([^"\s]+)"?/m.exec(
      text,
    )?.[1];
  } catch {
    return undefined;
  }
}

const key =
  process.env.AIC_LIVE_TESTS === '1' && existsSync(join(AUDIO, 'manifest.json'))
    ? (process.env.GEMINI_API_KEY ?? devKey())
    : undefined;

interface Clip {
  id: string;
  text: string;
  file: string;
  speechEndMs: number;
}

const RATE = 16_000;
const GAP_MS = 1500;

/** Clips back to back with gaps; returns the WAV path and when each clip's speech ends. */
function buildTrack(dir: string, name: string, clips: Clip[], leadMs: number) {
  const parts: Int16Array[] = [new Int16Array((RATE * leadMs) / 1000)];
  const ends: number[] = [];
  let at = leadMs;
  for (const clip of clips) {
    const wav = readWav(readFileSync(join(AUDIO, clip.file)));
    parts.push(wav.samples, new Int16Array((RATE * GAP_MS) / 1000));
    ends.push(at + clip.speechEndMs);
    at += (wav.samples.length / RATE) * 1000 + GAP_MS;
  }
  const all = new Int16Array(parts.reduce((n, p) => n + p.length, 0));
  let o = 0;
  for (const p of parts) {
    all.set(p, o);
    o += p.length;
  }
  const file = join(dir, name);
  writeFileSync(file, encodeWav(all));
  return { file, ends, durationMs: at };
}

describe.skipIf(!key)('live transcription with real Gemini', () => {
  const dir = mkdtempSync(join(tmpdir(), 'aic-live-stt-'));
  afterAll(() => rmSync(dir, { recursive: true, force: true }));

  it('transcribes both channels of an interview in real time', async () => {
    const manifest = JSON.parse(readFileSync(join(AUDIO, 'manifest.json'), 'utf8')) as Clip[];
    const interviewerClips = manifest.slice(0, 4);
    const candidateClip = manifest[6]!;
    const interviewer = buildTrack(dir, 'interviewer.wav', interviewerClips, 500);
    // The candidate talks in the gap after the interviewer's first question.
    const candidate = buildTrack(dir, 'candidate.wav', [candidateClip], interviewer.ends[0]! + 700);

    const events: { at: number; update: LiveTranscriptUpdate }[] = [];
    let t0 = 0;
    const engine = createEngine({
      emit: (event: keyof EngineEvents, data: unknown) => {
        if (event === 'live.transcript') {
          events.push({ at: performance.now() - t0, update: data as LiveTranscriptUpdate });
        }
      },
      exit: () => undefined,
      logToConsole: process.env.AIC_LIVE_VERBOSE === '1',
    });
    const h = engine.handlers;
    await h.init({
      dbPath: join(dir, 'app.db'),
      dbKeyHex: randomBytes(32).toString('hex'),
      backupDir: join(dir, 'bk'),
      logDir: join(dir, 'logs'),
      appVersion: 'live',
      fakeProvider: false,
      nativeAudioPath: null,
      audioReplay: { interviewer: interviewer.file, candidate: candidate.file },
    });
    await h['apiKey.activate']({ provider: 'gemini', key: key!, verification: null, models: null });

    t0 = performance.now();
    const started = await h['live.start']({
      mode: 'interview',
      title: 'Live STT check',
      profileId: null,
      knowledgeBaseId: null,
      transcribe: true,
    });
    await new Promise((r) => setTimeout(r, interviewer.durationMs + 4000));
    await h['live.stop']();

    const finals = events.filter((e) => e.update.kind === 'final');
    const mine = finals.filter((e) => e.update.segment.channel === 'interviewer');
    const latencies: number[] = [];
    for (const [i, clip] of interviewerClips.entries()) {
      const best = mine
        .map((e) => ({ e, sim: transcriptSimilarity(clip.text, e.update.segment.text) }))
        .sort((a, b) => b.sim - a.sim)[0];
      console.log(
        `${clip.id}: sim ${best?.sim.toFixed(2)} final +${best ? Math.round(best.e.at - interviewer.ends[i]!) : '-'} ms\n  ref: ${clip.text}\n  got: ${best?.e.update.segment.text}`,
      );
      expect(best?.sim ?? 0).toBeGreaterThan(0.8);
      if (best) latencies.push(best.e.at - interviewer.ends[i]!);
    }
    const firstInterim = events.find((e) => e.update.kind === 'interim');
    console.log(
      `first interim at ${Math.round(firstInterim?.at ?? -1)} ms (speech starts ~${500 + 600} ms); final after speech end: ${latencies.map((l) => Math.round(l)).join(', ')} ms`,
    );
    const theirs = finals.filter((e) => e.update.segment.channel === 'candidate');
    console.log(`candidate: ${theirs.map((e) => e.update.segment.text).join(' | ')}`);
    expect(
      theirs.some((e) => transcriptSimilarity(candidateClip.text, e.update.segment.text) > 0.7),
    ).toBe(true);

    const detail = await h['sessions.get']({ id: started.id });
    expect(detail.segments.length).toBeGreaterThanOrEqual(interviewerClips.length + 1);
    await h.shutdown();
  }, 120_000);
});
